create extension if not exists "uuid-ossp";
create table if not exists portaria_eventos(id uuid primary key default uuid_generate_v4(),created_at timestamptz default now(),data date default current_date,evento text not null,container_no text not null,batch text not null,doca text not null,hora time not null,status text not null,liberado boolean default false);
create table if not exists recebimento(id uuid primary key default uuid_generate_v4(),created_at timestamptz default now(),data date default current_date,seq integer,container_no text not null,processo text,batch text not null,hora_portaria_saida time,hora_recuo time,hora_inicio_descarga time,hora_final time,doca text not null,area text,tipo text,status text,turno text,fotos_count integer default 0);
create table if not exists producao(id uuid primary key default uuid_generate_v4(),created_at timestamptz default now(),linha text not null,ordem integer not null,batch text not null,produzido integer default 0,meta integer default 30);
create table if not exists unpacking(id uuid primary key default uuid_generate_v4(),created_at timestamptz default now(),data date default current_date,linha text,equipe text,turno text,batch text,pecas_recebidas integer default 0,caixas_finalizadas integer default 0,status text default 'Em andamento');
create table if not exists fotos_recebimento(id uuid primary key default uuid_generate_v4(),created_at timestamptz default now(),container_no text not null,batch text,tipo_foto text not null,file_path text not null,public_url text not null);
insert into storage.buckets (id,name,public) values ('fotos-recebimento','fotos-recebimento',true) on conflict (id) do nothing;
alter table portaria_eventos enable row level security; alter table recebimento enable row level security; alter table producao enable row level security; alter table unpacking enable row level security; alter table fotos_recebimento enable row level security;
create policy if not exists "read portaria" on portaria_eventos for select using (true); create policy if not exists "write portaria" on portaria_eventos for all using (true) with check (true);
create policy if not exists "read recebimento" on recebimento for select using (true); create policy if not exists "write recebimento" on recebimento for all using (true) with check (true);
create policy if not exists "read producao" on producao for select using (true); create policy if not exists "write producao" on producao for all using (true) with check (true);
create policy if not exists "read unpacking" on unpacking for select using (true); create policy if not exists "write unpacking" on unpacking for all using (true) with check (true);
create policy if not exists "read fotos" on fotos_recebimento for select using (true); create policy if not exists "write fotos" on fotos_recebimento for all using (true) with check (true);
create policy if not exists "upload fotos" on storage.objects for insert with check (bucket_id='fotos-recebimento'); create policy if not exists "read storage fotos" on storage.objects for select using (bucket_id='fotos-recebimento');
